    slug: "organization-admin-faq",
    title: "Organization admin FAQ",
    summary: "Quick answers for organization admins: linking Zebron quizzes, offering Zebron courses and certifications, publishing and deleting courses, and training groups.",
    applicationKey: "platform",
    contentType: "faq",
